function rwPool(id){const tp=[...WT,...RDT].find(x=>x.id===id);if(!tp._d){tp._d=1;const L=tp.q.map(q=>(q.p||"").length+q.o.join("").length),S=[...L].sort((a,b)=>a-b);tp.q.forEach((q,j)=>{q._d=S.indexOf(L[j])/S.length})}return tp}
function pickRW(list,level,used){const out=[];for(const [id,n] of list){const tp=rwPool(id),pool=tp.q.filter(q=>!used.has(id+"|"+q.t));let pref=level==="hi"?pool.filter(q=>q._d>=.5):level==="lo"?pool.filter(q=>q._d<.5):pool;pref=sh(pref.slice());const rest=sh(pool.filter(q=>!pref.includes(q)));for(const q of pref.concat(rest).slice(0,n)){used.add(id+"|"+q.t);out.push({...q,k:id,s:q.s||tp.stem,sec:"rw"})}}return out}
function pickM(level,used){const out=[];for(const d of ["A","V","P","G"]){const want=(d==="A"||d==="V"?MQ6:MQ5)[level],tc={};for(const df of want){const pool=MM.filter(q=>q.dom===d&&!used.has("m"+q.id));let c=pool.filter(q=>q.diff===df);if(!c.length)c=pool.filter(q=>Math.abs(q.diff-df)===1);if(!c.length)c=pool;c=sh(c.slice());c.sort((a,b)=>(tc[a.tpl]||0)-(tc[b.tpl]||0));const q=c[0];tc[q.tpl]=(tc[q.tpl]||0)+1;used.add("m"+q.id);out.push({...q,sec:"m"})}}return out.map(q=>[q.diff+Math.random()*.9,q]).sort((a,b)=>a[0]-b[0]).map(x=>x[1])}
