  document.body.appendChild(o);const I=o.querySelector("#ci"),Rr=o.querySelector("#cr");
  const ev=()=>{let s=I.value.replace(/×/g,"*").replace(/÷/g,"/").replace(/−/g,"-").replace(/\^/g,"**").replace(/π/g,"pi").replace(/√/g,"sqrt");CALC.ex=I.value;
    const t=s.replace(/sin|cos|tan|ln|log|sqrt|abs|pi/g,"");if(!/^[0-9+\-*/().,\s]*$/.test(t)){Rr.textContent="Xato";return}
    try{const d=CALC.deg,f=new Function("sin","cos","tan","ln","log","sqrt","abs","pi","return ("+s+")");const v=f(x=>Math.sin(d?x*Math.PI/180:x),x=>Math.cos(d?x*Math.PI/180:x),x=>Math.tan(d?x*Math.PI/180:x),Math.log,Math.log10,Math.sqrt,Math.abs,Math.PI);Rr.textContent=isFinite(v)?String(+v.toPrecision(10)):"Xato"}catch(e){Rr.textContent="Xato"}};
