const PSQ=[
["The senator's claim lacked ______: although she cited statistics, none could be traced to a reliable source, and several experts doubted her.",["credibility","generosity","readiness","complexity"],0,"CRED = ishonmoq. Credibility = ishonchlilik. Gapda dalillar ishonchsiz ekani aytilgan, shuning uchun senator da'vosida aynan ishonchlilik yetishmagan."],
["Because the soil had been ______ by decades of intensive farming, the harvest dwindled each year.",["demystified","depleted","transferred","interpreted"],1,"DE- = kamaytirmoq, olib tashlamoq. Deplete = tugatmoq, kamaytirib yubormoq: tuproqning unumdorligi tugagani uchun hosil kamaygan."],
["Researchers found the two species to be ______; neither could thrive without the other.",["interdependent","substandard","irresponsible","impartial"],0,"INTER- = o'zaro, dependent = qaram. Interdependent = o'zaro bog'liq. Ikkinchi qism ham shuni tasdiqlaydi."],
["Critics called the plan ______, arguing that it could not be justified by any evidence the agency had provided.",["transparent","supportive","unwarranted","generous"],2,"UN- = emas, warranted = asoslangan. Unwarranted = asossiz. Dalil yo'qligi aytilgani uchun aynan shu so'z mos."],
["The judge, known for her ______, refused to favor either party and ruled solely on the facts.",["malpractice","impartiality","dominance","prevalence"],1,"IM- = emas, partial = tarafkash. Impartial/impartiality = xolislik. Hech bir tarafni olmaslik shu ma'noni beradi."],
["The novelist's ______ prose, full of unexpected metaphors, set her apart from her contemporaries.",["careless","destructive","innovative","meaningless"],2,"-IVE = moyillik; innovative = yangilik qiluvchi. \"Kutilmagan metaforalar\" va \"zamondoshlaridan ajralib turishi\" yangilikka ishora."],
["The rumor, spread by a ______ coworker, was intended solely to damage her reputation.",["benevolent","credible","contradictory","malicious"],3,"MAL = yomon. Malicious = yomon niyatli. Obro'ga zarar yetkazish niyati shuni bildiradi; benevolent esa teskari ma'noda (BENE = yaxshi)."],
["The new law will ______ the way citizens interact with government by moving most services online.",["deplete","discredit","subordinate","transform"],3,"TRANS- = narigi tomonga, o'zgartirmoq. Transform = tubdan o'zgartirmoq. Xizmatlar onlayn bo'lsa, o'zaro aloqa shakli tubdan o'zgaradi."],
["Her ______ response to the crisis, waiting for more data before acting, prevented costly mistakes.",["cautious","contentious","relentless","powerless"],0,"-OUS = ... xususiyatli. Cautious = ehtiyotkor. Ma'lumot kutib turish ehtiyotkorlikka misol."],
["The economist ______ the importance of savings, mentioning it in every lecture.",["devalued","deconstructed","emphasized","interrupted"],2,"-IZE = qilmoq. Emphasize = ta'kidlamoq. Har ma'ruzada eslatish — ta'kidlash; devalue (qadrsizlantirish) esa teskari."],
["The company's ______ to adopt new technology gave it an advantage over slower competitors.",["ready","readiness","readily","readied"],1,"-NESS ot yasaydi: readiness = tayyorlik. Egalik shakli (company's) dan keyin ot kerak, shuning uchun sifat, ravish yoki fe'l mos emas."],
["Most of the evidence the author presents is ______, which makes it difficult to accept the conclusion without further proof.",["verifiable","contradictory","beneficial","subconscious"],1,"CONTRA = qarshi, DICT = aytmoq: contradictory = qarama-qarshi. Dalillar bir-biriga zid bo'lsa, xulosani isbotsiz qabul qilish qiyin. (Verifiable bo'lganda xulosa osonlashar edi.)"]
];
function rdPS(){
  const esc2=esc,G=[];PSD.split("\n\n").forEach(b=>{const L=b.trim().split("\n"),h=L[0].split("|");if(h.length<3)return;G.push({k:h[0],h:h[1],n:h[2],x:h[3]==="X",w:L.slice(1).filter(x=>x[0]!=="+").map(x=>x.split("|")),e:L.slice(1).filter(x=>x[0]==="+").map(x=>x.slice(1).split("|"))})});
  const row=([w,u])=>`<div class="psr"><b>${esc(w)}</b>${spkBtn(w)}<span>${esc(u)}</span></div>`;
  const grp=g=>`<div class="card psg"><div class="psh">${esc(g.h)}${g.x?` <span class="pstag">qo'shimcha</span>`:""}</div><div class="sub" style="margin:2px 0 8px">${esc(g.n)}</div>${g.w.map(row).join("")}${g.e.length?`<div class="sub" style="margin:8px 0 4px;font-size:.82rem">Qo'shimcha so'zlar:</div>${g.e.map(row).join("")}`:""}</div>`;
  const sec=(k,t,s)=>`<h2 class="h2">${t}</h2><p class="sub" style="margin:0 0 10px">${s}</p>${G.filter(g=>g.k===k).map(grp).join("")}`;
  const X=(h,b)=>`<h2 class="h2">${h}</h2><div class="xp">${b}</div>`;
  $.innerHTML=`<div class="wrap"><h1>PREFIXES &amp; SUFFIXES</h1><p class="sub">SAT English · Reading (Words in Context)</p>
  ${X("Nima uchun kerak?","<p>SAT'da notanish so'z uchraganda uning qismlariga qarab ma'nosini taxmin qilish mumkin. So'z uch qismdan iborat bo'lishi mumkin: <b>prefix</b> (old qo'shimcha) + <b>root</b> (ildiz) + <b>suffix</b> (oxirgi qo'shimcha).</p><p>Masalan: <b>dis·rupt·ion</b> → dis- (teskari) + rupt (sindirmoq) + -ion (ot) = <i>buzilish, to'xtalish</i>.</p><p class=\"sub\" style=\"font-size:.85rem\">Slayddagi so'zlar asosiy ro'yxatda, mening qo'shganlarim esa «Qo'shimcha so'zlar» sarlavhasi ostida va «qo'shimcha» belgisi bilan alohida ko'rsatilgan.</p>")}
  ${sec("P","1. Prefixes (old qo'shimchalar)","So'z boshiga qo'shilib ma'nosini o'zgartiradi.")}
  ${sec("S","2. Suffixes (oxirgi qo'shimchalar)","So'z oxiriga qo'shilib ma'no va so'z turkumini belgilaydi.")}
  ${sec("R","3. Roots (ildizlar)","So'zning asosiy ma'nosini beradi. Bir ildizdan ko'p so'z yasaladi.")}
  ${X("4. Suffix orqali so'z turkumini bilish","<p>Gap ichidagi bo'sh joyga qaysi so'z turkumi kerakligini aniqlash uchun suffix yordam beradi:</p><p><b>Ot (noun):</b> -ity, -ness, -ence/-ance, -tion, -ment, -ism, -ship, -ist, -er/-or</p><p><b>Fe'l (verb):</b> -ize, -ify, -ate</p><p><b>Sifat (adjective):</b> -ous, -ive, -less, -ful, -able/-ible, -al, -ic</p><p><b>Ravish (adverb):</b> -ly</p>")}
  ${X("5. SAT'da qo'llash strategiyasi","<p><b>1) Qismlarga ajrating.</b> Notanish so'zni prefix + root + suffix ga bo'ling va har birining ma'nosini qo'shing.</p><p><b>2) Ijobiy yoki salbiy ekanini aniqlang.</b> mal-, dis-, un-, in-, de- odatda salbiy; bene-, cred- ijobiy ma'no beradi. Gapning umumiy kayfiyati bilan solishtiring.</p><p><b>3) Gap ma'nosiga qarang.</b> Qo'shimcha so'zlar (but, because, although, while) mantiqiy aloqani ko'rsatadi. Ma'no gapga mos kelmasa, variantni olib tashlang.</p><p><b>4) So'z turkumini tekshiring.</b> Bo'sh joyga ot, sifat yoki fe'l kerakligini suffix orqali aniqlang.</p>")}
  ${X("6. Ehtiyot bo'ling: adashtiradigan so'zlar","<p>• <b>in-</b> har doim «emas» degani emas: <i>inhabit</i> (yashamoq), <i>inflammable</i> (yonuvchan, ya'ni yonadigan), <i>invaluable</i> (juda qimmatli, qiymati o'lchab bo'lmaydigan).</p><p>• <b>disinterested</b> = xolis, betaraf; <b>uninterested</b> = qiziqmaydigan. Bular bir xil emas.</p><p>• <b>unravel</b> (yechmoq, tushunib yetmoq) va <b>ravel</b> deyarli bir xil ma'noda, un- bu yerda kuchaytiradi.</p><p>• <b>regard</b> = e'tibor; <b>disregard</b> = e'tiborsiz qoldirmoq (teskari).</p>")}
  <h2 class="h2">7. Mashq savollari</h2><p class="sub" style="margin:0 0 10px">Which choice completes the text with the most logical and precise word or phrase? Variantni bosing.</p>
  ${PSQ.map((q,n)=>`<div class="card" data-q="${n}"><p class="pl" style="margin:0 0 8px"><b>${n+1}.</b> ${esc(q[0])}</p>${q[1].map((o,i)=>`<button class="btn" data-i="${i}" style="margin:0 0 6px">${"ABCD"[i]}) ${esc(o)}</button>`).join("")}<div class="psx"></div></div>`).join("")}
  <button class="btn" id="hm">Orqaga</button></div>`;
  bindSpk($);
  qs("#hm").onclick=readingThemes;
  $.querySelectorAll("[data-q]").forEach(c=>{const q=PSQ[+c.dataset.q];c.querySelectorAll("[data-i]").forEach(b=>b.onclick=()=>{if(c.dataset.d)return;c.dataset.d=1;const i=+b.dataset.i;c.querySelectorAll("[data-i]").forEach(x=>{if(+x.dataset.i===q[2])x.classList.add("ok")});if(i!==q[2])b.classList.add("bad");c.querySelector(".psx").innerHTML=`<p class="sub" style="margin:10px 0 0"><b>${i===q[2]?"To'g'ri!":"Noto'g'ri."} To'g'ri javob: ${"ABCD"[q[2]]}.</b> ${esc(q[3])}</p>`})});
}
