let DIAG="";
async function detect(){
  const t=TOKEN();if(!t)return false;
  try{const r=await fetch("/api/me",{headers:{Authorization:"Bearer "+t}});IS_OWNER=r.ok;if(r.status===401)clearToken()}catch(e){}
  return IS_OWNER;
}
async function login(pw){
  try{
    const r=await fetch("/api/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({password:pw})});
    if(!r.ok){DIAG=r.status===401?"Parol noto'g'ri. Qayta urinib ko'ring.":"Tekshirib bo'lmadi, birozdan keyin qayta urinib ko'ring.";return false}
    const j=await r.json();setToken(j.token);IS_OWNER=true;return true;
  }catch(e){DIAG="Server bilan aloqa yo'q. Birozdan keyin qayta urinib ko'ring.";return false}
}
