(function(){
  const ICON='<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 5l-7 7 7 7"/></svg>';
  const fix=()=>{
    const root=document.getElementById("app")||$;if(!root)return;
    const w=root.querySelector(".wrap");if(!w||w.querySelector("#bkt"))return;
    const bs=[...w.querySelectorAll("button")].filter(b=>b.textContent.trim()==="Orqaga"&&b.id!=="mbk");
    w.querySelectorAll("button#hm").forEach(b=>b.classList.add("back"));bs.forEach(b=>b.classList.add("back"));
    const src=bs[bs.length-1];if(!src)return;
    const t=document.createElement("button");t.id="bkt";t.className="chip bkt";t.setAttribute("aria-label","Orqaga");t.title="Orqaga";t.innerHTML=ICON;
    t.onclick=()=>src.click();w.insertBefore(t,w.firstChild);
  };
  new MutationObserver(fix).observe($,{childList:true});fix();
})();
